def solve():
    quarterly_returns_str = "4%, -2%, 5%, 3%"

    # Parse the string input into a list of decimal floats
    quarterly_returns_list = []
    for r_str in quarterly_returns_str.replace(' ', '').split(','):
        # Convert percentage string to float decimal (e.g., "4%" -> 0.04)
        quarterly_returns_list.append(float(r_str.strip('%')) / 100)

    def calculate_portfolio_hpr(quarterly_returns: list) -> float:
        cumulative_return = 1
        for q_return in quarterly_returns:
